/**
 * Utility functions for GUI compatibility between lil-gui and Three.js Inspector.
 * @module guiUtils
 */
/**
 * Bind an onChange callback to a GUI controller.
 * Works with both lil-gui (onChange method) and Inspector API (addEventListener).
 *
 * @param {Object} ctrl - The GUI controller returned by add(), addColor(), etc.
 * @param {Function} callback - The callback function to execute on change.
 * @returns {Object} The controller for chaining.
 */
export function bindChange(ctrl: any, callback: Function): any;
/**
 * Safely call disable() on a controller if available.
 * Inspector API doesn't support disable().
 *
 * @param {Object} ctrl - The GUI controller.
 * @returns {Object} The controller for chaining.
 */
export function safeDisable(ctrl: any): any;
/**
 * Safely call listen() on a controller if available.
 * Inspector API supports listen() but it's good to check.
 *
 * @param {Object} ctrl - The GUI controller.
 * @returns {Object} The controller for chaining.
 */
export function safeListen(ctrl: any): any;
/**
 * Safely call updateDisplay() on a controller if available.
 * Inspector API doesn't support updateDisplay().
 *
 * @param {Object} ctrl - The GUI controller.
 * @returns {Object} The controller for chaining.
 */
export function safeUpdateDisplay(ctrl: any): any;
/**
 * Dispose a GUI folder/group safely.
 * Works with both lil-gui (destroy) and Inspector API (parent.remove).
 *
 * @param {Object} folder - The GUI folder to dispose.
 * @returns {null}
 */
export function disposeFolder(folder: any): null;
